16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = {PetMapper.class})
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.service.OwnerCheckDigitPolicy.checkDigit(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(org.springframework.samples.petclinic.service.OwnerMembershipPolicy.membershipNumber(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(org.springframework.samples.petclinic.service.OwnerMembershipLevelPolicy.membershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.service.OwnerLocalityPolicy.locality(owner))")
27	    @Mapping(target = "bulkSignupWarning", expression = "java(org.springframework.samples.petclinic.service.OwnerBulkSignupPolicy.bulkSignupWarning(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(org.springframework.samples.petclinic.service.OwnerContactPreferencePolicy.contactPreference(owner))")
29	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.service.OwnerIdentityPolicy.identityKey(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    Owner toOwner(OwnerDto ownerDto);
33	
34	    @Mapping(target = "id", ignore = true)
35	    @Mapping(target = "pets", ignore = true)
36	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
37	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
38	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
39	    Owner toOwner(OwnerFieldsDto ownerDto);
40	
41	    /**
42	     * Canonicalise the address on create: trim, collapse whitespace runs, upper-case, and expand
43	     * the common street-type abbreviations. The normalized value is what gets stored, returned, and
44	     * compared by the household rules.
45	     */
46	    @Named("normalizeAddress")
47	    default String normalizeAddress(String address) {
48	        if (address == null) {
49	            return null;
50	        }
51	        return address.trim().replaceAll("\\s+", " ").toUpperCase()
52	            .replaceAll("\\bST\\b", "STREET")
53	            .replaceAll("\\bRD\\b", "ROAD")
54	            .replaceAll("\\bAVE\\b", "AVENUE");
55	    }
56	
57	    /** Store the telephone in E.164 form (see {@link E164Telephone#toE164}). */
58	    @Named("normalizeTelephone")
59	    default String normalizeTelephone(String telephone) {
60	        return E164Telephone.toE164(telephone);
61	    }
62	
63	    /** Lower-case the email so it is stored and returned in canonical form. */
64	    @Named("normalizeEmail")
65	    default String normalizeEmail(String email) {
66	        return email == null ? null : email.toLowerCase();
67	    }
68	
69	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
70	
71	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
72	
73	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
74	        OwnerPageDto ownerPageDto = new OwnerPageDto();
75	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
76	        ownerPageDto.setPage(ownerPage.getNumber());
77	        ownerPageDto.setSize(ownerPage.getSize());
78	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
79	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
80	        return ownerPageDto;
81	    }
82	}
